`fadeToGray` must return a newly allocated RGBA color whose red, green, and blue channels are linearly blended toward luminance `0.2126*r + 0.7152*g + 0.0722*b` by `amount`. Round output RGB channels to the nearest integer and clamp all returned channels to `[0,255]`. Preserve the input alpha after rounding and clamping; the fade must not make a translucent color opaque. Require every input channel and `amount` to be finite, and require `amount` in `[0,1]`, otherwise throw `RangeError`. Do not mutate the input.

Known-bad source:

```ts
export interface Rgba {
  readonly r: number;
  readonly g: number;
  readonly b: number;
  readonly a: number;
}

function channel(value: number): number {
  return Math.min(255, Math.max(0, Math.round(value)));
}

export function fadeToGray(input: Rgba, amount: number): Rgba {
  if (!input || ![input.r, input.g, input.b, input.a, amount].every(Number.isFinite) ||
      amount < 0 || amount > 1) {
    throw new RangeError("Invalid color or amount");
  }
  const gray = 0.2126 * input.r + 0.7152 * input.g + 0.0722 * input.b;
  const blend = (value: number): number => channel(value + (gray - value) * amount);
  return { r: blend(input.r), g: blend(input.g), b: blend(input.b), a: 255 };
}
```

