import { fadeToGray, type Rgba } from "./solution";

function assert(condition: unknown, message: string): asserts condition {
  if (!condition) throw new Error(message);
}
function same(actual: unknown, expected: unknown, message: string): void {
  if (!Object.is(actual, expected)) throw new Error(message);
}
function throwsRangeError(action: () => unknown, message: string): void {
  let error: unknown;
  try { action(); } catch (caught) { error = caught; }
  assert(error instanceof RangeError, message);
}

const input: Rgba = { r: 100, g: 150, b: 200, a: 12.6 };
const result = fadeToGray(input, 0.5);
assert(result !== input, "result must be newly allocated");
same(result.r, 121, "red blend or rounding is incorrect");
same(result.g, 146, "green blend or rounding is incorrect");
same(result.b, 171, "blue blend or rounding is incorrect");
same(result.a, 13, "alpha must be preserved after rounding");
same(input.r, 100, "input red was mutated");
same(input.g, 150, "input green was mutated");
same(input.b, 200, "input blue was mutated");
same(input.a, 12.6, "input alpha was mutated");

const redGray = fadeToGray({ r: 255, g: 0, b: 0, a: 40 }, 1);
same(redGray.r, 54, "luminance red channel is incorrect");
same(redGray.g, 54, "luminance green channel is incorrect");
same(redGray.b, 54, "luminance blue channel is incorrect");
same(redGray.a, 40, "full fade must not make alpha opaque");

const boundary = fadeToGray({ r: -10.4, g: 127.5, b: 300.2, a: 300 }, 0);
same(boundary.r, 0, "returned red must be clamped");
same(boundary.g, 128, "returned green must be rounded");
same(boundary.b, 255, "returned blue must be clamped");
same(boundary.a, 255, "returned alpha must be rounded and clamped");
const transparent = fadeToGray({ r: 0, g: 0, b: 0, a: -2 }, 0);
same(transparent.a, 0, "negative alpha must clamp to zero");

for (const amount of [-0.01, 1.01, NaN, Infinity, -Infinity]) {
  throwsRangeError(() => fadeToGray(input, amount), "invalid amount was accepted: " + amount);
}
for (const key of ["r", "g", "b", "a"] as const) {
  const malformed: any = { r: 1, g: 2, b: 3, a: 4 };
  malformed[key] = NaN;
  throwsRangeError(() => fadeToGray(malformed, 0.5), "non-finite channel was accepted: " + key);
}
throwsRangeError(() => fadeToGray(null as any, 0.5), "null input must be rejected");
throwsRangeError(() => fadeToGray({ r: "1", g: 2, b: 3, a: 4 } as any, 0.5), "non-number channels must be rejected");

